function shelfLine(library) {
  const titles = library.titles();
  if (titles.length === 0) {
    return '(empty)';
  }
  return titles.join(', ');
}

function availability(library, isbn) {
  const book = library.find(isbn);
  if (!book) {
    return 'not found';
  }
  return `${book.available}/${book.copies}`;
}

module.exports = { shelfLine, availability };

